Index: data/samples/generate-f70-feedback-test.ts
===================================================================
--- data/samples/generate-f70-feedback-test.ts	
+++ data/samples/generate-f70-feedback-test.ts	
@@ -0,0 +1,16 @@
+// Regenerate only these invented artifacts: node data/samples/generate-f70-feedback-test.ts
+import { writeFileSync } from "node:fs";
+import { join } from "node:path";
+import writeXlsxFile from "write-excel-file/node";
+import { feedbackHeader, feedbackRows, feedbackSheet } from "./f70-feedback-test.fixture.ts";
+
+if (feedbackRows.length !== 100 || feedbackRows.some((row) => row.length !== 12)) {
+  throw new Error("Expected exactly 100 synthetic rows of 12 cells.");
+}
+const rows = [feedbackHeader, ...feedbackRows];
+const csv = rows.map((row) => row.map((cell) => `"${cell.replaceAll('"', '""')}"`).join(","));
+writeFileSync(join(import.meta.dirname, "f70-feedback-test.csv"), csv.join("\n") + "\n", "utf8");
+await writeXlsxFile([{ sheet: feedbackSheet, data: rows }]).toFile(
+  join(import.meta.dirname, "f70-feedback-test.xlsx"),
+);
+console.log("Generated synthetic F70 feedback: 100 data rows, 12 columns, one Feedback_Explorer sheet.");

Index: packages/blocks/src/raw/f70-feedback-test.test.ts
===================================================================
--- packages/blocks/src/raw/f70-feedback-test.test.ts	
+++ packages/blocks/src/raw/f70-feedback-test.test.ts	
@@ -0,0 +1,110 @@
+import { readFileSync } from "node:fs";
+import { join } from "node:path";
+import { DEFAULT_SETTINGS, PipelineData, Requirement, defaultBlockParams } from "@reqflow/core";
+import { createLlmClient } from "@reqflow/llm";
+import { describe, expect, it } from "vitest";
+import { feedbackHeader, feedbackRows, feedbackSheet, duplicateIds, independentCopyIds } from "../../../../data/samples/f70-feedback-test.fixture";
+import { classifyRequirement } from "../../../../apps/desktop/src/renderer/src/components/car/classify";
+import { agents, context } from "../add-to-car/test-helpers";
+import { addToCarBlock } from "../add-to-car/add-to-car";
+import { aiSplitterBlock } from "../ai-splitter/ai-splitter";
+import { hilBlock } from "../hil/hil";
+import { parseCsv } from "./csv";
+import { rawBlock } from "./raw";
+
+async function ingest(extension = "xlsx") {
+  const c = context(agents({ provider: "mock" }));
+  const name = `f70-feedback-test.${extension}`;
+  c.ctx.files = {
+    get: async () => ({
+      id: "file_synthetic_f70", name, mimeType: "application/octet-stream",
+      bytes: new Uint8Array(readFileSync(join(import.meta.dirname, "../../../../data/samples", name))),
+    }),
+  };
+  const result = await rawBlock.run({}, {
+    ...defaultBlockParams("raw"), dataset: "customer_feedback", sheet: feedbackSheet,
+    file: { fileId: "file_synthetic_f70", name },
+  }, c.ctx);
+  if (result.status !== "ok") throw new Error("Synthetic feedback ingestion failed.");
+  return { ...c, data: PipelineData.parse(result.outputs.out) };
+}
+
+describe("synthetic 100-row F70 workbook", () => {
+  it("contains exactly the export schema and 101 physical CSV lines", () => {
+    expect(feedbackHeader).toHaveLength(12);
+    expect(feedbackRows).toHaveLength(100);
+    expect(feedbackRows.every((row) => row.length === 12)).toBe(true);
+    const csv = readFileSync(join(import.meta.dirname, "../../../../data/samples/f70-feedback-test.csv"), "utf8");
+    expect(csv.trimEnd().split("\n")).toHaveLength(101);
+    expect(parseCsv(csv)).toEqual([feedbackHeader, ...feedbackRows]);
+    expect(feedbackRows.every((row) => row[1] === "SYNTHETIC TEST - NOT BMW DATA")).toBe(true);
+  });
+
+  it.each(["xlsx", "csv"])("ingests %s into 97 records with duplicate classifications merged", async (extension) => {
+    const { data, logs } = await ingest(extension);
+    expect(data.sources).toHaveLength(1);
+    expect(data.records).toHaveLength(97);
+    expect(data.findings).toHaveLength(0);
+    expect(data.records.every((r) => /^[A-Z]{2}$/.test(r.market ?? ""))).toBe(true);
+    for (const id of [...duplicateIds, ...independentCopyIds]) {
+      expect(data.records.filter((r) => r.fields?.ID === id)).toHaveLength(1);
+    }
+    expect(logs.join("\n")).toMatch(/Merged 99 rows into 97 records/);
+    expect(logs.join("\n")).toMatch(/without comment text/);
+  });
+
+  it("pauses at HIL and publishes seven proposed offline categories after review", async () => {
+    const { ctx, data, added, audit } = await ingest();
+    expect((await hilBlock.run({ in: data }, defaultBlockParams("hil"), ctx)).status).toBe("paused");
+    const resumed = await hilBlock.run({ in: data }, defaultBlockParams("hil"), { ...ctx, resumed: true });
+    expect(resumed).toEqual({ status: "ok", outputs: { out: data } });
+    await addToCarBlock.run({ "in-1": data }, {
+      ...defaultBlockParams("add_to_car"), contexts: [], maxRequirements: 10,
+    }, ctx);
+    const requirements = added.flatMap((a) => a.requirements);
+    expect(requirements).toHaveLength(7);
+    expect(requirements.map((r) => r.category).sort()).toEqual([
+      "comfort", "driving_experience", "exterior_design", "infotainment_digital",
+      "interior_quality", "space_practicality", "usability_controls",
+    ]);
+    expect(requirements.every((r) => r.status === "proposed" && r.priority === "should" && r.evidenceLevel === "C")).toBe(true);
+    expect(audit.filter((e) => e.action === "finding.excluded")).toHaveLength(4);
+    for (const r of requirements) Requirement.parse(r);
+    const evidence = added[0]!.evidence!;
+    const texts = new Map(evidence.records!.map((r) => [r.id, r.text]));
+    for (const finding of evidence.findings!) {
+      for (const excerpt of finding.evidence) expect(texts.get(excerpt.recordId!)).toContain(excerpt.excerpt);
+    }
+    console.log("SYNTHETIC baseline", JSON.stringify(requirements.map((r) => ({
+      category: r.category, priority: r.priority, findings: r.findingIds.length,
+      part: classifyRequirement(r).partId,
+    }))));
+  });
+
+  it("routes every record exactly once with customer-priority mock and publishes ranked categories", async () => {
+    const { ctx, data, added } = await ingest();
+    ctx.llm = createLlmClient({ ...DEFAULT_SETTINGS.llm, provider: "mock" });
+    const split = await aiSplitterBlock.run({ in: data }, defaultBlockParams("ai_splitter"), ctx);
+    if (split.status !== "ok" || !split.splitterReport) throw new Error("Expected a saved splitter analysis.");
+    const ids = Object.values(split.outputs).flatMap((d) => d.records.map((r) => r.id));
+    expect(ids).toHaveLength(97);
+    expect(new Set(ids).size).toBe(97);
+    expect(new Set(ids)).toEqual(new Set(data.records.map((r) => r.id)));
+    console.log("SYNTHETIC splitter", JSON.stringify({
+      counts: Object.fromEntries(Object.entries(split.outputs).map(([port, d]) => [port, d.records.length])),
+      groups: split.splitterReport.groups.map((g) => ({
+        label: g.label, support: g.support, oppose: g.oppose, unclear: g.unclear,
+        score: g.score, port: g.outputPortId,
+      })),
+    }));
+    await addToCarBlock.run({
+      "in-0": split.outputs["out-0"]!, "in-1": split.outputs["out-1"]!, "in-2": split.outputs["out-2"]!,
+    }, { ...defaultBlockParams("add_to_car"), contexts: [], maxRequirements: 10 }, ctx);
+    const requirements = added.flatMap((a) => a.requirements);
+    expect(requirements).toHaveLength(7);
+    expect(requirements.every((r) => r.status === "proposed")).toBe(true);
+    console.log("SYNTHETIC ranked", JSON.stringify(requirements.map((r) => ({
+      category: r.category, priority: r.priority, findings: r.findingIds.length, part: classifyRequirement(r).partId,
+    }))));
+  });
+});

